// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Eip1271Signer signer;
    MockToken token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        signer = new Eip1271Signer();
        token = new MockToken();
    }

    function testFuzz_property(uint256 premium, uint256 duration, uint256 expiration, uint256 nonce, address filler) public {
        vm.assume(filler != address(0));
        duration = bound(duration, 0, 10_000 days - 1);
        expiration = bound(expiration, block.timestamp + 1, type(uint256).max / 2);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(signer),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(65);
        vm.startPrank(filler);
        bool ok = true;
        try c.fillOrder(order, sig, floorAssetTokenIds) {}
        catch {
            ok = false;
        }
        vm.stopPrank();
        assertTrue(ok, "long order fill must succeed");

        uint256 longPositionId = uint256(c.hashOrder(order));
        assertTrue(
            c.positionExpirations(longPositionId) == block.timestamp + duration,
            "long position expiration must be stored at the long position id"
        );
    }
}

contract Eip1271Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract MockToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
